-- Append-only audit trail (generated by scripts/gen-audit-migration.ts).
-- Actor and request come from transaction-local settings written by lib/prisma.ts.

CREATE OR REPLACE FUNCTION audit_row() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE
  v_old jsonb;
  v_new jsonb;
  v_action "AuditAction";
  v_id text;
  v_company uuid;
  v_user text := NULLIF(current_setting('app.user_id', true), '');
  v_admin bigint := NULLIF(current_setting('app.admin_id', true), '')::bigint;
  v_request text := NULLIF(current_setting('app.request_id', true), '');
  v_actor text := COALESCE(NULLIF(current_setting('app.actor_type', true), ''), 'system');
  v_impersonator text := NULLIF(current_setting('app.impersonated_by', true), '');
BEGIN
  IF TG_OP = 'INSERT' THEN
    v_new := to_jsonb(NEW); v_action := 'CREATE';
  ELSIF TG_OP = 'UPDATE' THEN
    v_old := to_jsonb(OLD); v_new := to_jsonb(NEW); v_action := 'UPDATE';
    IF v_old = v_new THEN RETURN NEW; END IF;
  ELSE
    v_old := to_jsonb(OLD); v_action := 'DELETE';
  END IF;
  v_id := COALESCE(v_new->>TG_ARGV[0], v_old->>TG_ARGV[0]);
  IF TG_ARGV[1] = 'company' THEN
    v_company := COALESCE(v_new->>'company_id', v_old->>'company_id')::uuid;
  ELSIF TG_TABLE_NAME = 'companies' THEN
    v_company := v_id::uuid;
  END IF;
  -- Secrets never enter the trail.
  v_old := v_old - 'passwordHash' - 'password_hash' - 'sessionToken' - 'accessToken' - 'refreshToken' - 'mfaSecret' - 'mfa_secret' - 'tokenHash' - 'token_hash' - 'prev_token_hash';
  v_new := v_new - 'passwordHash' - 'password_hash' - 'sessionToken' - 'accessToken' - 'refreshToken' - 'mfaSecret' - 'mfa_secret' - 'tokenHash' - 'token_hash' - 'prev_token_hash';
  INSERT INTO audit_log (company_id, "entityName", "entityId", action, "oldValues", "newValues",
    "changedBy", "changedByAdmin", request_id, actor_type, impersonated_by, "changedAt")
  VALUES (v_company, TG_TABLE_NAME, v_id, v_action, v_old, v_new,
    v_user, v_admin, v_request, v_actor, v_impersonator, now());
  RETURN COALESCE(NEW, OLD);
END $$;

-- audit_log is append-only: only the retention sweep (8-year floor) may remove rows.
CREATE OR REPLACE FUNCTION audit_log_guard() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF COALESCE(current_setting('app.retention_sweep', true), 'off') = 'on' AND TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RAISE EXCEPTION 'audit_log is append-only (% refused)', TG_OP USING ERRCODE = 'insufficient_privilege';
END $$;
DROP TRIGGER IF EXISTS audit_log_immutable ON audit_log;
CREATE TRIGGER audit_log_immutable BEFORE UPDATE OR DELETE ON audit_log FOR EACH ROW EXECUTE FUNCTION audit_log_guard();

DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'shiftline_app') THEN
    REVOKE UPDATE, DELETE ON audit_log FROM shiftline_app;
  END IF;
END $$;

DROP TRIGGER IF EXISTS audit_vouchers ON "vouchers";
CREATE TRIGGER audit_vouchers AFTER INSERT OR UPDATE OR DELETE ON "vouchers" FOR EACH ROW EXECUTE FUNCTION audit_row('id', 'company');
